import{_ as a,o as e,a as _,b as r}from"./app.DAp7B6qI.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/cube_store_key_features"},{"text":"随路量化与随路ReLU场景组合","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization_and_relu_scenario_combination"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization_and_relu_scenario_combination.md","filePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization_and_relu_scenario_combination.md","lastUpdated":1789544578000}'),i={name:"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization_and_relu_scenario_combination.md"};function n(d,t,o,b,c,R){return e(),_("div",null,[...t[0]||(t[0]=[r('<div><article class="markdown-body"><h1>随路量化与随路ReLU场景组合</h1><p>矩阵搬出支持多种随路量化与随路ReLU的组合，常用的不激活/Normal ReLU组合参考下表，Scalar/Vector扩展组合见后文。</p><div data-filter="950,A3,910b"><p>随路量化与随路ReLU的组合情况如下表所示：</p><div data-filter="A3,910b"><p><strong>表1</strong> 随路量化与随路ReLU的组合表（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>）</p><table><thead><tr><th>quant_pre / relu_pre</th><th>0（不激活）</th><th>1（Normal ReLU）</th></tr></thead><tbody><tr><td>•REQ8<br>•DEQF16<br>•QF322B8_PRE</td><td>M1=QUANT_PRE[31:0]<br>M2=QUANT_PRE[31:0]<br>M1、M2均为量化参数</td><td>M1=QUANT_PRE[31:0]<br>M2=0<br>M1为量化参数、M2为NORMAL系数</td></tr><tr><td>•VREQ8<br>•VDEQF16<br>•VQF322B8_PRE</td><td>M1=Quant_PRE_ADDR[i][31:0]<br>M2=Quant_PRE_ADDR[i][31:0]<br>M1、M2均为量化参数，i为原始矩阵的列索引</td><td>M1=Quant_PRE_ADDR[i][31:0]<br>M2=0<br>M1为量化参数，M2为NORMAL系数，i为原始矩阵的列索引</td></tr></tbody></table></div><div data-filter="950"><p><strong>表2</strong> 随路量化与随路ReLU的组合表（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）</p><table><thead><tr><th>quant_pre_mode / relu_pre_mode</th><th>NONE</th><th>NORMAL</th></tr></thead><tbody><tr><td>•REQ8<br>•DEQF16<br>•QF322B8_PRE<br>•QF322FP8_PRE<br>•QF322HIF8_PRE<br>•QF322HIF8_PRE_HYBRID<br>•QS322BF16_PRE<br>•QF322F16_PRE<br>•QF322BF16_PRE<br>•QF322F32_PRE</td><td>M1=QUANT_PRE[31:13]<br>M2=QUANT_PRE[31:13]<br>M1、M2均为量化参数</td><td>M1=QUANT_PRE[31:13]<br>M2=0<br>M1为量化参数、M2为NORMAL系数</td></tr><tr><td>•VREQ8<br>•VDEQF16<br>•VQF322B8_PRE<br>•VQF322FP8_PRE<br>•VQF322HIF8_PRE<br>•VQF322HIF8_PRE_HYBRID<br>•VQS322BF16_PRE<br>•VQF322F16_PRE<br>•VQF322BF16_PRE<br>•VQF322F32_PRE</td><td>M1=Quant_PRE_ADDR[i][31:13]<br>M2=Quant_PRE_ADDR[i][31:13]<br>M1、M2均为量化参数，i为原始矩阵的列索引</td><td>M1=Quant_PRE_ADDR[i][31:13]<br>M2=0<br>M1为量化参数，M2为NORMAL系数，i为原始矩阵的列索引</td></tr></tbody></table></div><p>注：M1为原始数据非负时使用的随路系数，M2为原始数据为负数时使用的随路系数。</p></div></article></div>',1)])])}const s=a(i,[["render",n]]);export{p as __pageData,s as default};
